import { IBaseRouteObject, IBaseRouteObjectPoint, RouteObjectType } from '../@types/routes.types';
import { obstacleCategoryNameResource } from './../../Obstacles/@resources/obstacles.resource';

export const getRouteThreadItems = (routeObjects: IBaseRouteObject[]): string[] => {
  const pointsInDistance = routeObjects.filter(
    (mo) => mo.type === RouteObjectType.Point && mo.is_in_distance,
  ) as IBaseRouteObjectPoint[];
  const routeThread = pointsInDistance.map((ro) => {
    if (ro.obstacle) {
      return `${ro.obstacle.name} (${obstacleCategoryNameResource[ro.obstacle.category]}, ${ro.obstacle.altitude})`;
    }
    return ro.name;
  });

  return routeThread;
};
